// tests/bin/write-loops.test.js
//
// web/loops/index.json is generated by bin/write-loops.js and must never be edited by hand: running the generator has to give back the file that is
// committed, or the data and the patterns it says it comes from have drifted. A command that exits 0 having produced nothing is a failure too.
import { describe, it, expect } from 'vitest'
import { execFileSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

const root = resolve(import.meta.dirname, '../..')
const file = resolve(root, 'web/loops/index.json')

describe('bin/write-loops.js', () => {
  it('writes exactly the library that is in the repository, and says how many loops it wrote', () => {
    const before = readFileSync(file, 'utf8')
    const output = execFileSync('node', ['bin/write-loops.js'], { cwd: root, encoding: 'utf8' })
    expect(output).toMatch(/web\/loops\/index\.json: \d+ loops/)
    expect(readFileSync(file, 'utf8')).toBe(before)
  })

  it('names itself and the command that regenerates the file, so a person who finds it knows not to edit it', () => {
    const index = JSON.parse(readFileSync(file, 'utf8'))
    expect(index.generated).toBe('bin/write-loops.js')
    expect(index.note).toMatch(/Do not edit; run npm run build:loops/)
    expect(JSON.parse(readFileSync(resolve(root, 'package.json'), 'utf8')).scripts['build:loops']).toBe('node bin/write-loops.js')
  })
})
